<?php
require 'config.php'; require_login();
$runs=$pdo->query("SELECT r.id,r.site_id,r.started_at,r.status,r.total_errors,r.total_unchecked,s.name,s.start_url,s.allowed_domains,s.max_pages,s.max_depth,s.request_timeout,s.max_duration FROM scan_runs r JOIN sites s ON s.id=r.site_id ORDER BY r.id DESC")->fetchAll();$a=max(0,(int)($_GET['a']??0));$b=max(0,(int)($_GET['b']??0));$old=[];$new=[];$newErrors=[];$resolved=[];$unknown=[];$err='';
if($a&&$b&&$a!==$b){$q=$pdo->prepare('SELECT normalized_url,status_category,error_detail FROM findings WHERE run_id=?');$q->execute([$a]);foreach($q->fetchAll() as $f)$old[$f['normalized_url']]=$f;$q->execute([$b]);foreach($q->fetchAll() as $f)$new[$f['normalized_url']]=$f;if(!$old||!$new)$err='Một trong hai phiên chưa có kết quả để so sánh.';else{$scopeA=null;$scopeB=null;foreach($runs as $rr){if((int)$rr['id']===$a)$scopeA=$rr;if((int)$rr['id']===$b)$scopeB=$rr;}if(!$scopeA||!$scopeB||$scopeA['start_url']!==$scopeB['start_url']||trim((string)$scopeA['allowed_domains'])!==trim((string)$scopeB['allowed_domains'])||(int)$scopeA['max_pages']!==(int)$scopeB['max_pages']||(int)$scopeA['max_depth']!==(int)$scopeB['max_depth']||(float)$scopeA['request_timeout']!==(float)$scopeB['request_timeout']||(float)$scopeA['max_duration']!==(float)$scopeB['max_duration']){$err='Hai phiên có phạm vi/cấu hình khác nhau. Chỉ nên so sánh cùng URL gốc, allowlist và giới hạn quét.';}else{foreach($new as $url=>$f){if(in_array($f['status_category'],['unknown','unchecked'],true))$unknown[$url]=$f;if(in_array($f['status_category'],['http_error','connection_error','missing_anchor'],true)&&(!isset($old[$url])||!in_array($old[$url]['status_category'],['http_error','connection_error','missing_anchor'],true)))$newErrors[$url]=$f;}foreach($old as $url=>$f)if(in_array($f['status_category'],['http_error','connection_error','missing_anchor'],true)&&isset($new[$url])&&!in_array($new[$url]['status_category'],['http_error','connection_error','missing_anchor'],true))$resolved[$url]=$new[$url];}}}
layout_start('So sánh phiên quét'); ?>
<div class="mb-4"><div class="small-label mb-2">SCAN DIFF</div><h1 class="h3 page-title">So sánh hai lần quét</h1><p class="muted">Đối chiếu lỗi mới, lỗi đã xử lý và mục chưa xác định.</p></div><div class="card p-4 mb-4"><form method="get" class="row g-3 align-items-end"><div class="col-md-5"><label class="form-label fw-semibold">Phiên cũ</label><select class="form-select" name="a" required><?php foreach($runs as $r):?><option value="<?=$r['id']?>" <?=$a===(int)$r['id']?'selected':''?>>#<?=$r['id']?> · <?=e($r['name'])?> · <?=e($r['started_at'])?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label fw-semibold">Phiên mới</label><select class="form-select" name="b" required><?php foreach($runs as $r):?><option value="<?=$r['id']?>" <?=$b===(int)$r['id']?'selected':''?>>#<?=$r['id']?> · <?=e($r['name'])?> · <?=e($r['started_at'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">So sánh</button></div></form></div>
<?php if($err!==''):?><div class="alert alert-warning"><?=e($err)?></div><?php elseif($a&&$b):?><div class="row g-3 mb-4"><?php foreach([['Lỗi mới',count($newErrors),'danger'],['Lỗi đã xử lý',count($resolved),'success'],['Chưa xác định / bỏ qua',count($unknown),'warning']] as $m):?><div class="col-md-4"><div class="card p-4"><div class="muted"><?=e($m[0])?></div><div class="metric text-<?=$m[2]?>"><?=$m[1]?></div></div></div><?php endforeach;?></div><?php foreach([['Lỗi mới',$newErrors,'danger'],['Lỗi đã xử lý',$resolved,'success'],['Chưa xác định / bỏ qua',$unknown,'warning']] as $section):?><div class="card p-4 mb-4"><h2 class="h5 fw-bold mb-3"><?=e($section[0])?></h2><?php if(!$section[1]):?><p class="muted mb-0">Không có mục nào trong nhóm này.</p><?php else:?><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>URL</th><th>Trạng thái hiện tại</th><th>Chi tiết</th></tr></thead><tbody><?php foreach($section[1] as $url=>$f):?><tr><td class="wrap-url"><?=e($url)?></td><td><?=e($f['status_category'])?></td><td><?=e($f['error_detail'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php endforeach;?><?php endif;?><?php layout_end(); ?>